"""IB DP Global Politics (SL/HL, first assessment 2026) – ib-g11-political-science.

Content pack for the QB-IB engine. Items use the Global Politics key concepts (power, sovereignty,
legitimacy, interdependence, rights, justice, liberty, equality, development, sustainability, peace,
conflict, violence), named theorists and real contemporary cases (UN, EU, ASEAN, AU, ICC, NGOs,
social movements).

Mock = one paper set mirroring examPattern in targets.json (paper marks are UNVERIFIED there):
  Paper 1 (source-based, 4 sources, 4 questions: 3 + 4 + 8 + 10 = 25 marks)
  Paper 2 (extended response: four essay prompts, candidates answer two, 15 marks each, markbands)
  Paper 3 HL (stimulus-based questions on a global political challenge: 4 + 9 + 15 marks)
Paper 1 items draw on chapter-level source sets (P1); Paper 2 / Paper 3 items reuse each subtopic's
`evaluate` claims and `cases`. Mock-only templates return None outside their own mock section.
"""
from __future__ import annotations

from _common import F, Registry, T, mcq, name  # noqa: F401

CONFIG = {'minutesPerMark': 2.5, 'mcqMinutes': 1.0}

MOCK = [
    dict(section='Paper 1 – Q1 Identify (source-based)', count=1, c=['C3'], d=[2], marks=3, style='p1q1'),
    dict(section='Paper 1 – Q2 Explain with reference to a source', count=1, c=['C3'], d=[3], marks=4, style='p1q2'),
    dict(section='Paper 1 – Q3 Compare and contrast two sources', count=1, c=['C4'], d=[3], marks=8, style='p1q3'),
    dict(section='Paper 1 – Q4 Evaluate using sources and own knowledge', count=1, c=['C4'], d=[4], marks=10, style='p1q4'),
    dict(section='Paper 2 – Extended response (answer two of four)', count=4, c=['C4'], d=[4, 5], marks=15, style='p2'),
    dict(section='Paper 3 (HL) – Q1 Stimulus: explain', count=1, c=['C3'], d=[3], marks=4, style='p3q1'),
    dict(section='Paper 3 (HL) – Q2 Stimulus: analyse', count=1, c=['C3'], d=[4], marks=9, style='p3q2'),
    dict(section='Paper 3 (HL) – Q3 Stimulus: evaluate', count=1, c=['C4'], d=[5], marks=15, style='p3q3'),
]

MARKBAND = ('Markbands (15): 13–15 – sharply focused on the demands of the question; detailed, accurate '
            'knowledge of relevant concepts, theories and specific contemporary examples; well-developed, '
            'balanced counter-claims; a clear, consistent and well-supported conclusion. 10–12 – focused and '
            'well structured; relevant, accurate knowledge and examples; counter-claims addressed; reasoned '
            'conclusion. 7–9 – mostly focused; relevant knowledge with some examples; some counter-claims; '
            'conclusion stated. 4–6 – some understanding of the demands; limited or general knowledge, '
            'mainly descriptive; little evaluation. 1–3 – little understanding; minimal relevant knowledge; '
            'no evaluation. 0 – does not reach the standard of band 1.')
BANDS_GENERIC = ('Markbands (scaled to the marks available, five bands): top band – sharply focused, accurate knowledge of '
                 'concepts, theories and specific examples, well-developed counter-claims and a clear, well-supported '
                 'judgement; upper-middle – focused, relevant examples, counter-claims addressed, reasoned conclusion; '
                 'middle – mostly focused, some examples and counter-claims, conclusion stated; lower – limited, mainly '
                 'descriptive knowledge with little evaluation; bottom – minimal relevant knowledge, no evaluation.')
BANDS_10 = ('Markbands (10): 9–10 – focused, balanced argument with specific, accurate examples and a well-supported '
            'judgement; 7–8 – relevant examples, counter-claims considered, reasoned judgement; 5–6 – some relevant '
            'knowledge, partly descriptive, judgement asserted; 3–4 – limited, general knowledge with little evaluation; '
            '1–2 – minimal relevant material.')
STYLE = {'eval_marks': 10, 'essay_marks': 15, 'markband': BANDS_GENERIC}

R = Registry()
P1: dict = {}   # chapter 'chNN' -> dict(src=[...], cmp=[...], ev=[...])


def templates(st):
    return R.build(st, STYLE)


def lc(s):
    w = s.split(' ', 1)[0]
    if len(w) > 1 and (w[1].isupper() or w[1].isdigit()):
        return s
    return s[0].lower() + s[1:]


# =============================================================================================
# Mock-only templates (Paper 1, Paper 2, Paper 3 HL)
# =============================================================================================
LAB = 'ABCD'
P1_Q4_BANDS = ('Markbands (10): 9–10 – focused response using all relevant sources and well-chosen own knowledge, '
               'balanced analysis and a well-supported judgement; 7–8 – uses sources and own knowledge with some '
               'balance and a judgement; 5–6 – some use of sources or own knowledge, mostly descriptive, partial '
               'judgement; 3–4 – limited use of sources, general own knowledge; 1–2 – little relevant material. '
               'Responses that use only the sources or only own knowledge cannot go above 6.')


def _block(ch, i):
    s = P1[ch]['src'][i]
    return f'Source {LAB[i]}\n{s[0]}\n— {s[1]}'


def _ch(slot):
    return slot.subtopic['id'].rsplit('-', 2)[-2]


def _p1q1(rng, slot):
    if slot.style != 'p1q1' or _ch(slot) not in P1:
        return None
    ch = _ch(slot)
    i = rng.randrange(len(P1[ch]['src']))
    s = P1[ch]['src'][i]
    q = s[2].replace('{S}', f'Source {LAB[i]}')
    return dict(stem=f'Paper 1 – Question 1. Read Source {LAB[i]}.\n\n{_block(ch, i)}\n\n{q} [3]', answer='; '.join(s[3]),
                markingKey='Award 1 mark for each of the following, up to 3 marks: ' + '; '.join(s[3]) +
                '. Points must be drawn from the source; accept close paraphrase.', type='case', marks=3, gap='G7')


def _p1q2(rng, slot):
    if slot.style != 'p1q2' or _ch(slot) not in P1:
        return None
    ch = _ch(slot)
    i = rng.randrange(len(P1[ch]['src']))
    s = P1[ch]['src'][i]
    q = s[4].replace('{S}', f'Source {LAB[i]}')
    return dict(stem=f'Paper 1 – Question 2. Read Source {LAB[i]}.\n\n{_block(ch, i)}\n\n{q} [4]', answer=s[5],
                markingKey=f'{s[5]} 3–4 marks: clear explanation with explicit, relevant reference to the source; '
                '1–2 marks: limited explanation or mainly quotation/description without explanation.',
                type='case', marks=4, gap='G7')


def _p1q3(rng, slot):
    if slot.style != 'p1q3' or _ch(slot) not in P1:
        return None
    ch = _ch(slot)
    i, j, focus, sims, diffs = rng.choice(P1[ch]['cmp'])
    return dict(stem=f'Paper 1 – Question 3. Read Sources {LAB[i]} and {LAB[j]}.\n\n{_block(ch, i)}\n\n{_block(ch, j)}\n\n'
                     f'Compare and contrast the views presented in Source {LAB[i]} and Source {LAB[j]} on {focus}. [8]',
                answer='Similarities: ' + '; '.join(sims) + '. Differences: ' + '; '.join(diffs) + '.',
                markingKey='Similarities: ' + '; '.join(sims) + '. Differences: ' + '; '.join(diffs) +
                '. Award 1 mark per valid, source-referenced point of comparison or contrast (up to 8). If only '
                'similarities or only differences are addressed, award a maximum of 4 marks. Reward a running '
                'comparison above two separate descriptions.', type='case', marks=8, gap='G7')


def _p1q4(rng, slot):
    if slot.style != 'p1q4' or _ch(slot) not in P1:
        return None
    ch = _ch(slot)
    i, j, claim, pro, con = rng.choice(P1[ch]['ev'])
    return dict(stem=f'Paper 1 – Question 4. Read Sources {LAB[i]} and {LAB[j]}.\n\n{_block(ch, i)}\n\n{_block(ch, j)}\n\n'
                     f'Using Sources {LAB[i]} and {LAB[j]} and your own knowledge, evaluate the claim that {claim} [10]',
                answer='Supporting: ' + '; '.join(pro) + '. Challenging: ' + '; '.join(con) + '.',
                markingKey='Supporting: ' + '; '.join(pro) + '. Challenging: ' + '; '.join(con) + '. ' + P1_Q4_BANDS,
                type='long', marks=10, gap='G5')


P2_FRAMES = [
    'Evaluate the claim that {c} In your answer, refer to at least two contrasting examples.',
    'To what extent do you agree that {c2}? Support your answer with specific contemporary case studies.',
    '"{C}" Discuss, with reference to at least one theoretical perspective and two real-world examples.',
    'Examine the view that {c} Use relevant key concepts and named examples in your answer.',
]


def _p2(rng, slot):
    f = R.f.get(slot.subtopic['id'].rsplit('-', 2)[-2] + '-' + slot.subtopic['id'].rsplit('-', 1)[-1])
    if slot.style != 'p2' or not f or not f.evaluate:
        return None
    claim, pro, con, judge = rng.choice(f.evaluate)
    fr = rng.choice(P2_FRAMES)
    stem = 'Paper 2 – ' + fr.format(c=lc(claim), c2=lc(claim).rstrip('.'), C=claim) + ' [15]'
    key = ('Arguments for: ' + '; '.join(pro) + '. Arguments against: ' + '; '.join(con) +
           f'. Possible judgement: {judge} ' + MARKBAND)
    return dict(stem=stem, answer=judge, markingKey=key, type='long', marks=15, gap='G5')


def _stkey(slot):
    return slot.subtopic['id'].rsplit('-', 2)[-2] + '-' + slot.subtopic['id'].rsplit('-', 1)[-1]


def _p3q1(rng, slot):
    f = R.f.get(_stkey(slot))
    if slot.style != 'p3q1' or not f or not f.cases:
        return None
    case, what, concept, how = rng.choice(f.cases)
    return dict(stem=f'Paper 3 – Question 1. Read the stimulus.\n\nStimulus: {what}\n\nWith reference to the stimulus, '
                     f'explain one way in which {case} illustrates {concept}. [4]',
                answer=how, markingKey=f'{how.rstrip(".")}. 1 mark for identifying a relevant feature from the stimulus; up to 3 further '
                'marks for explaining clearly how it links to the concept.', type='case', marks=4, gap='G7')


def _p3q2(rng, slot):
    f = R.f.get(_stkey(slot))
    if slot.style != 'p3q2' or not f or not f.cases:
        return None
    case, what, concept, how = rng.choice(f.cases)
    return dict(stem=f'Paper 3 – Question 2. Read the stimulus.\n\nStimulus: {what}\n\nUsing the stimulus and one other '
                     f'example you have studied, analyse the roles of the actors involved in {case} in relation to {concept}. [9]',
                answer=f'{how.rstrip(".")}. A second, contrasting example is analysed alongside the stimulus.',
                markingKey=f'Stimulus: {how.rstrip(".")}. Own example must be specific and explicitly compared. 7–9: sustained analysis of '
                'actors and the concept, using both stimulus and own example; 4–6: some analysis, uneven use of the '
                'stimulus or example; 1–3: mostly descriptive.', type='long', marks=9, gap='G5')


def _p3q3(rng, slot):
    f = R.f.get(_stkey(slot))
    if slot.style != 'p3q3' or not f or not f.cases or not f.evaluate:
        return None
    case, what, concept, how = rng.choice(f.cases)
    claim, pro, con, judge = rng.choice(f.evaluate)
    return dict(stem=f'Paper 3 – Question 3. Read the stimulus.\n\nStimulus: {what}\n\n"{claim}" With reference to the '
                     'stimulus and your own knowledge, to what extent do you agree with this statement? [15]',
                answer=judge, markingKey='Arguments for: ' + '; '.join(pro) + '. Arguments against: ' + '; '.join(con) +
                f'. Possible judgement: {judge} The stimulus should be used as evidence, not merely summarised. ' + MARKBAND,
                type='long', marks=15, gap='G5')


BANK_ESSAY = [
    '"{C}" How far do you agree? Justify your answer with reference to at least one key concept.',
    'Assess the validity of the claim that {c}',
    'With reference to two specific examples you have studied, evaluate the argument that {c}',
    '"{C}" Using one theoretical perspective and relevant case studies, discuss this view.',
]


def _bank_essay(rng, slot):
    f = R.f.get(_stkey(slot))
    if slot.style or not f or not f.evaluate:
        return None
    claim, pro, con, judge = rng.choice(f.evaluate)
    stem = rng.choice(BANK_ESSAY).format(c=lc(claim), C=claim)
    m = 15 if slot.d >= 5 else 10
    key = ('Arguments for: ' + '; '.join(pro) + '. Arguments against: ' + '; '.join(con) +
           f'. Supported judgement: {judge} ' + (MARKBAND if m == 15 else BANDS_10))
    return dict(stem=stem, answer=judge, markingKey=key, type='long', marks=m, gap='G5')


MOCK_T = [(_p1q1, 'C3', 'p1q1', 'case'), (_p1q2, 'C3', 'p1q2', 'case'), (_p1q3, 'C4', 'p1q3', 'case'),
          (_p1q4, 'C4', 'p1q4', 'long'), (_p2, 'C4', 'p2', 'long'), (_p3q1, 'C3', 'p3q1', 'case'),
          (_p3q2, 'C3', 'p3q2', 'long'), (_p3q3, 'C4', 'p3q3', 'long')]
_DONE = []


def init(subject_id):
    if _DONE:
        return
    _DONE.append(1)
    for key in list(R.f):
        for fn, c, sty, ty in MOCK_T:
            R.add(key, c, (1, 5), ty, style=sty)(fn)
        R.add(key, 'C4', (4, 5), 'long')(_bank_essay)


