# =============================================================================================
# ch11 Development and Sustainability – factors, pathways and actors
# =============================================================================================
R.facts('ch11-st1', F(
    terms=[('good governance', 'the exercise of authority through accountable, transparent, participatory and effective institutions that respect the rule of law'),
           ('corruption', 'the abuse of entrusted power for private gain (Transparency International)'),
           ('resource curse', 'the paradox that countries rich in natural resources often have slower growth, weaker institutions and more conflict than resource-poor countries'),
           ('official development assistance (ODA)', 'government aid designed to promote the economic development and welfare of developing countries, including grants and concessional loans'),
           ('debt distress', 'a situation in which a country cannot meet its debt service obligations without major adjustment, restructuring or default'),
           ('terms of trade', 'the ratio of a country\'s export prices to its import prices')],
    facts=[('Which of the following organizations publishes the Corruption Perceptions Index?', 'Transparency International', ['The World Bank', 'Freedom House', 'Amnesty International'], 'The CPI ranks countries from 0 (highly corrupt) to 100 (very clean).'),
           ('Which of the following is the UN target for official development assistance as a share of donors\' gross national income?', '0.7%', ['0.07%', '7%', '1.5%'], 'Only a few donors such as Norway, Sweden, Luxembourg and Denmark regularly meet it.'),
           ('Which of the following books by Dambisa Moyo (2009) argued that aid has harmed Africa\'s development?', 'Dead Aid', ['The End of Poverty', 'The White Man\'s Burden', 'Why Nations Fail'], 'Sachs (The End of Poverty) argued for more aid; Easterly criticised top-down aid.'),
           ('Which of the following initiatives, launched in 1996 by the IMF and World Bank, provided debt relief to the world\'s poorest countries?', 'The Heavily Indebted Poor Countries (HIPC) Initiative', ['The Marshall Plan', 'The Belt and Road Initiative', 'The Common Agricultural Policy'], 'It was supplemented by the Multilateral Debt Relief Initiative in 2005.')],
    why=[('Explain why corruption hinders development.', 'It diverts public funds from schools and hospitals, raises costs for businesses, deters investment, and undermines trust in institutions and the rule of law, so resources do not reach intended beneficiaries.'),
         ('Explain why high levels of external debt can limit development.', 'Debt service payments take revenue away from health, education and infrastructure; debt crises force austerity and may reduce access to new finance (e.g. Sri Lanka 2022, Zambia 2020).'),
         ('Explain why trade rules can disadvantage developing countries.', 'Agricultural subsidies in rich countries (e.g. US cotton subsidies) depress world prices, tariff escalation discourages processing, and limited bargaining power in the WTO restricts developing countries\' influence over rules.')],
    contrast=[('bilateral aid', 'multilateral aid', 'Bilateral aid is given directly from one government to another (e.g. USAID, which was largely dismantled in 2025); multilateral aid is channelled through international organizations such as the World Bank or UN agencies.'),
              ('tied aid', 'untied aid', 'Tied aid requires recipients to spend funds on goods and services from the donor country; untied aid can be spent anywhere, which usually gives better value.')],
    misc=[('Countries with abundant natural resources always develop faster.', 'Many resource-rich countries suffer from the resource curse – corruption, conflict, Dutch disease and volatility – while Botswana shows good governance can avoid it.'),
          ('Aid always leads to development.', 'Aid effectiveness depends on governance, design and context; poorly targeted or tied aid can create dependency and support corrupt elites, while well-designed health aid (e.g. Gavi, Global Fund) has saved millions of lives.')],
    cases=[('Botswana and diamonds', 'Since independence in 1966 Botswana has used diamond revenues, managed through a joint venture with De Beers (Debswana), to fund education and infrastructure, becoming an upper-middle-income country.', 'avoiding the resource curse through governance', 'accountable institutions and prudent revenue management turned resource wealth into development'),
           ('Sri Lanka\'s 2022 debt crisis', 'Sri Lanka defaulted on its foreign debt in 2022 amid shortages of fuel and medicine; mass protests forced President Gotabaya Rajapaksa to resign, and an IMF programme followed in 2023.', 'debt as an obstacle to development', 'unsustainable borrowing and policy errors caused a crisis that reversed development gains and triggered political upheaval'),
           ('the Global Fund to Fight AIDS, Tuberculosis and Malaria', 'Created in 2002, the Global Fund reports that its partnership has saved tens of millions of lives through funding for treatment and prevention.', 'effective aid', 'targeted, measurable health aid shows aid can deliver significant development outcomes'),
           ('the 1MDB scandal in Malaysia', 'Billions of dollars were embezzled from a state investment fund; former prime minister Najib Razak was convicted in 2020.', 'corruption and development', 'public funds intended for development were stolen, damaging trust and public finances')],
    apply=[('A low-income country receives large aid flows but scores 20 out of 100 on the Corruption Perceptions Index. Suggest two ways donors could reduce the risk that aid is wasted and explain one.', 'Channel aid through NGOs or multilateral agencies; results-based financing; budget transparency and audits; cash transfers directly to households (e.g. GiveDirectly in Kenya). E.g. direct transfers bypass corrupt intermediaries.', 4),
           ('Identify whether each factor is likely to promote or hinder development and explain briefly: (a) an independent judiciary, (b) dependence on a single commodity export, (c) remittances from migrants.', '(a) promotes – rule of law protects contracts and rights; (b) hinders – vulnerability to price shocks; (c) usually promotes – income for households, but may create dependency/brain drain. 1 mark each.', 3)],
    sources=[('"The problem was never only the amount of money. It was that the money went to the wrong people – or to projects nobody asked for."', 'Development NGO worker in East Africa, 2019 (adapted)', 'With reference to the source, explain one reason aid may fail to promote development.', 'Aid may be captured by elites through corruption ("wrong people") or be donor-driven and poorly suited to local needs ("projects nobody asked for"), reducing effectiveness.'),
             ('"This year we will spend more on interest to foreign creditors than on our entire health system."', 'Finance minister of an African country, 2023 (adapted)', 'Explain, with reference to the source, how debt can hinder development.', 'Debt service crowds out spending on health and other services; resources leave the country to creditors rather than funding development.')],
    evaluate=[('Good governance is the most important factor for development.', ['Botswana vs other resource-rich states', 'corruption diverts funds', 'Acemoglu and Robinson: inclusive institutions'],
               ['China grew rapidly despite limited democratic governance', 'external factors – debt, trade rules, climate', 'geography and colonial legacies'],
               'Governance is crucial, but its effects interact with external structures; good governance is necessary but not sufficient.'),
              ('Aid does more harm than good.', ['Moyo: dependency and corruption', 'Easterly: top-down planning', 'tied aid'],
               ['health aid saves millions (Global Fund, Gavi)', 'emergency relief', 'Sachs: big push'],
               'Aid\'s impact varies; well-targeted aid can be highly effective, while aid that bypasses local ownership or props up corrupt regimes can do harm.')],
    extended=[('Analyse the factors that have promoted or hindered development in one country you have studied.', 'Choose a country (e.g. Botswana, Rwanda, Nigeria, Bangladesh, Sri Lanka); analyse governance, corruption, debt, trade and aid; weigh internal versus external factors.', 8, 'long')],
))

R.facts('ch11-st2', F(
    terms=[('Washington Consensus', 'a set of ten market-oriented policy prescriptions summarised by John Williamson in 1989, including fiscal discipline, trade liberalisation, privatisation and deregulation'),
           ('Beijing Consensus', 'a term coined by Joshua Cooper Ramo in 2004 for China\'s development model of state-led, gradual reform, innovation and self-determination'),
           ('developmental state', 'a state that actively directs economic development through industrial policy, investment and close cooperation with business, as in Japan and South Korea'),
           ('structural adjustment programmes (SAPs)', 'IMF and World Bank loan programmes of the 1980s–1990s requiring market reforms such as cutting subsidies, privatising and liberalising trade'),
           ('export-led growth', 'a development strategy based on expanding exports, often of manufactured goods, to drive economic growth'),
           ('industrial policy', 'government measures to promote particular industries or sectors, such as subsidies, tariffs or public investment')],
    facts=[('Which of the following economists summarised the "Washington Consensus" in 1989?', 'John Williamson', ['Joseph Stiglitz', 'Milton Friedman', 'Joshua Cooper Ramo'], 'Williamson listed ten reforms for Latin America.'),
           ('Which of the following scholars described Japan\'s MITI as the core of a "developmental state" in 1982?', 'Chalmers Johnson', ['Ha-Joon Chang', 'Walt Rostow', 'Andre Gunder Frank'], 'MITI and the Japanese Miracle (1982).'),
           ('Which of the following countries carried out "Doi Moi" reforms from 1986, combining market reforms with one-party rule?', 'Vietnam', ['Cambodia', 'Laos', 'Myanmar'], 'Vietnam became one of the fastest-growing economies in Asia.'),
           ('Which of the following is a typical Washington Consensus policy?', 'Privatisation of state-owned enterprises', ['High tariffs to protect infant industries', 'State control of banking', 'Capital controls on foreign investment'], 'The Consensus favoured market liberalisation.')],
    why=[('Explain why the Washington Consensus was criticised.', 'Rapid liberalisation and austerity under SAPs often increased poverty and inequality, cut health and education spending, and caused instability (e.g. capital account liberalisation before the 1997 Asian crisis); critics such as Joseph Stiglitz argued it was "one size fits all".'),
         ('Explain why the Chinese model is attractive to some developing-country governments.', 'It combines rapid growth and poverty reduction with political stability and state control, offers infrastructure finance without governance conditions, and does not require liberal democratic reforms.'),
         ('Explain why East Asian developmental states challenged free-market orthodoxy.', 'South Korea and Taiwan used tariffs, subsidies, credit allocation and export targets to build industries (e.g. Samsung, Hyundai), contradicting the claim that minimal state intervention is best.')],
    contrast=[('the Washington Consensus', 'the Beijing Consensus', 'The Washington Consensus prescribes market liberalisation, privatisation and fiscal discipline with a limited state; the Beijing Consensus describes state-led, gradual, experimental reform with a strong state role and political stability.'),
              ('import substitution', 'export-led growth', 'Import substitution protects domestic industry to replace imports and serve the home market (Latin America 1950s–70s); export-led growth promotes production for world markets (East Asian tigers).')],
    misc=[('China developed by following the Washington Consensus.', 'China liberalised gradually but retained state-owned enterprises, capital controls, state banks and industrial policy – very different from the Washington Consensus.'),
          ('State-led development always leads to inefficiency and failure.', 'Developmental states such as South Korea and Taiwan achieved rapid growth through state guidance, though state-led strategies have also failed elsewhere (e.g. some ISI cases).')],
    cases=[('Ghana\'s structural adjustment in the 1980s', 'Under IMF and World Bank programmes from 1983, Ghana devalued its currency, liberalised trade and cut subsidies; growth recovered but critics noted rising user fees for health and education.', 'the Washington Consensus in practice', 'market reforms restored growth but imposed social costs, illustrating the debate over SAPs'),
           ('Ethiopia\'s developmental state', 'From the 2000s Ethiopia pursued state-led investment in infrastructure, industrial parks and the Grand Ethiopian Renaissance Dam, achieving rapid growth before conflict and debt problems after 2020.', 'state-led development in Africa', 'the state drove investment and growth, but political conflict and debt exposed risks of the model'),
           ('Argentina\'s 2001 crisis', 'After a decade of liberalisation, privatisation and a currency peg, Argentina defaulted on about $95 billion of debt in 2001, causing a deep recession and political turmoil.', 'criticism of neoliberal reform', 'the crisis was widely cited as a failure of Washington Consensus-style policies'),
           ('Vietnam\'s Doi Moi', 'Since 1986 Vietnam has opened to foreign investment and exports while retaining Communist Party rule; extreme poverty fell dramatically and it became a major electronics exporter.', 'the Beijing Consensus model', 'gradual market reform under a strong one-party state produced rapid growth')],
    apply=[('A developing country is advised to cut tariffs, privatise its electricity company and reduce its budget deficit. Identify the development pathway and outline one potential benefit and one risk.', 'Washington Consensus. Benefit: efficiency, investment, fiscal stability. Risk: job losses, higher electricity prices, inequality, infant industries collapse. 1+1+1(+1 development).', 4),
           ('Identify the pathway illustrated by each: (a) South Korea\'s state-directed credit to chaebol in the 1970s, (b) Chile\'s privatisation of pensions in 1981, (c) China\'s Special Economic Zones from 1980.', '(a) developmental state/state-led; (b) Washington Consensus/neoliberal; (c) Beijing Consensus/state-led gradual opening. 1 mark each.', 3)],
    sources=[('"We were told to privatise, liberalise and stabilise. We did all three. Our growth returned, but so did hunger in the countryside."', 'Former African finance official, 2010 (adapted)', 'With reference to the source, explain one criticism of structural adjustment.', 'Market reforms ("privatise, liberalise, stabilise") restored growth but imposed social costs (rural hunger) because subsidies and services were cut – growth without inclusive development.'),
             ('"Cross the river by feeling the stones."', 'Saying associated with Deng Xiaoping\'s approach to reform in China', 'Explain, with reference to the source, a feature of China\'s development pathway.', 'Gradual, experimental reform – testing policies (e.g. Special Economic Zones) before scaling up – rather than rapid "shock therapy" liberalisation.')],
    evaluate=[('State-led development is more effective than market-led development.', ['East Asian tigers, China, Vietnam', 'market failures need state action', 'Washington Consensus failures (Argentina 2001)'],
               ['state failure and corruption', 'Soviet-style planning collapse', 'market reforms in India (1991) boosted growth'],
               'Successful cases combine markets with a capable, disciplined state; the question is less state vs market than the quality of the state.'),
              ('The Beijing Consensus offers a better model of development for the Global South than the Washington Consensus.', ['China\'s growth and poverty reduction', 'infrastructure focus', 'no governance conditions'],
               ['depends on China\'s specific conditions', 'authoritarian costs', 'debt from BRI loans'],
               'China\'s experience offers lessons on state capacity and gradualism, but it is not easily replicated, and no single model fits all.')],
    extended=[('Compare two countries that followed different pathways to development and evaluate their outcomes.', 'E.g. Chile (neoliberal) vs South Korea (developmental state), or Ghana (SAPs) vs Vietnam (Doi Moi). Compare policies, growth, inequality, social outcomes and political consequences.', 8, 'long')],
))

R.facts('ch11-st3', F(
    terms=[('World Bank', 'an international financial institution founded at Bretton Woods (1944) that provides loans, grants and advice to developing countries for development projects'),
           ('International Monetary Fund (IMF)', 'an international organization founded at Bretton Woods that supports monetary cooperation and lends to countries facing balance-of-payments problems'),
           ('remittances', 'money sent home by migrants working abroad to their families'),
           ('microfinance', 'the provision of small loans and financial services to poor people who lack access to banks, pioneered by the Grameen Bank'),
           ('foreign direct investment (FDI)', 'investment by a company in productive assets in another country, such as a factory'),
           ('brain drain', 'the emigration of highly skilled and educated people from a country')],
    facts=[('Which of the following founded the Grameen Bank and shared the 2006 Nobel Peace Prize?', 'Muhammad Yunus', ['Amartya Sen', 'Mahbub ul Haq', 'Wangari Maathai'], 'Yunus became head of Bangladesh\'s interim government in 2024.'),
           ('Which of the following conferences in 1944 created the IMF and the World Bank?', 'The Bretton Woods Conference', ['The Yalta Conference', 'The Potsdam Conference', 'The San Francisco Conference'], 'The San Francisco Conference (1945) created the UN.'),
           ('Which of the following countries receives remittances equal to more than 40% of its GDP?', 'Tajikistan', ['Brazil', 'China', 'Nigeria'], 'Tajikistan relies heavily on migrants working in Russia.'),
           ('Which of the following is the IMF\'s main role?', 'Lending to countries with balance-of-payments problems and monitoring the global economy', ['Financing individual infrastructure projects only', 'Setting world trade tariffs', 'Running UN peacekeeping operations'], 'The World Bank focuses on long-term development lending.')],
    why=[('Explain why remittances can be more effective than aid in reducing poverty.', 'Remittances go directly to households, are spent on immediate needs (food, education, health), avoid government bureaucracy and corruption, and are larger than total ODA to low- and middle-income countries.'),
         ('Explain why MNCs can both promote and hinder development.', 'They bring investment, jobs, technology and exports, but may repatriate profits, avoid taxes, exploit low wages, damage the environment and crowd out local firms.'),
         ('Explain why the World Bank has been criticised for some of its projects.', 'Large infrastructure projects such as dams have displaced communities and harmed the environment (e.g. the Narmada dam controversy led the Bank to withdraw in 1993), and loans have come with conditions favouring market reforms.')],
    contrast=[('the IMF', 'the World Bank', 'The IMF focuses on macroeconomic stability and short- to medium-term balance-of-payments lending with policy conditions; the World Bank focuses on long-term development projects and poverty reduction in areas such as infrastructure, health and education.'),
              ('FDI', 'remittances', 'FDI is investment by firms in productive assets abroad, driven by profit; remittances are transfers from migrants to families, driven by household needs.')],
    misc=[('Microfinance has been proven to lift most borrowers out of poverty.', 'Randomised evaluations (e.g. Banerjee and Duflo) found modest average effects on income; microfinance has also been linked to over-indebtedness crises, such as in Andhra Pradesh in 2010.'),
          ('The IMF and World Bank give each member state one equal vote.', 'Votes are weighted by quotas/capital shares, giving the US and other large economies the largest shares; by convention the World Bank president has been American and the IMF managing director European.')],
    cases=[('Shell in the Niger Delta', 'Oil production by Shell and other companies has been linked to oil spills and pollution in Ogoniland; a 2011 UNEP report recommended a major clean-up, and in 2024 Shell agreed to sell its Nigerian onshore subsidiary.', 'the negative impact of MNCs on development', 'oil wealth produced revenue for the state but environmental damage and conflict for local communities'),
           ('M-Pesa in Kenya', 'Launched by Safaricom (partly owned by Vodafone) in 2007, the mobile-money service is used by most Kenyan adults; research found it helped lift around 2% of Kenyan households out of poverty.', 'the role of private actors in development', 'a technology company expanded financial inclusion, showing how private innovation can promote development'),
           ('remittances to Nepal', 'Remittances from Nepali migrants in the Gulf, Malaysia and India have equalled roughly a quarter of GDP and helped reduce poverty.', 'remittances as a pathway of development', 'household income from abroad funds consumption and education, though it reflects a lack of domestic jobs'),
           ('BRAC in Bangladesh', 'BRAC, founded in 1972, became one of the world\'s largest NGOs, running schools, health programmes and microfinance, and its "graduation" approach for the ultra-poor has been adopted elsewhere.', 'the role of NGOs in development', 'an NGO delivered services at scale and pioneered approaches later used by governments and donors')],
    apply=[('A country\'s migrants send home remittances worth 25% of GDP. Outline one benefit and two risks for the country\'s development.', 'Benefit: household income, consumption, schooling, foreign exchange. Risks: dependency on host economies (e.g. Russian downturn hitting Tajikistan), brain drain, weak incentives for domestic job creation, family separation. 1+2 (+1 explanation).', 4),
           ('Identify the most appropriate actor for each task: (a) an emergency loan to stabilise a collapsing currency, (b) a 20-year loan for rural roads, (c) small loans to women entrepreneurs in villages.', '(a) IMF; (b) World Bank (IDA/IBRD); (c) microfinance institution or NGO (e.g. Grameen, BRAC). 1 mark each.', 3)],
    sources=[('"My son in Dubai pays for his sisters\' school and my medicine. The government gives us nothing; Dubai gives us everything."', 'Interview with a mother in rural Nepal, 2019 (adapted)', 'With reference to the source, explain the importance of remittances in development.', 'Remittances provide direct household income for education and health, compensating for weak state provision; they are a major development resource for many families.'),
             ('"The Fund\'s loan came with forty conditions. Parliament was told to pass them within weeks, or the money would not arrive."', 'Commentary by a Latin American economist, 2019 (adapted)', 'Explain, with reference to the source, a criticism of the IMF.', 'IMF conditionality can impose many policy changes quickly, limiting democratic deliberation and national policy autonomy (sovereignty).')],
    evaluate=[('The IMF and World Bank have done more to hinder than to promote development.', ['SAPs cut services and increased poverty', 'conditionality undermines sovereignty', 'unequal voting'],
               ['emergency lending prevents collapse', 'HIPC debt relief', 'World Bank funds health, education, infrastructure', 'reforms since 2000s (poverty reduction strategies)'],
               'Their record is mixed: harmful in the SAP era, more positive since reforms, but governance and conditionality remain controversial.'),
              ('Non-state actors are now more important than states in promoting development.', ['remittances exceed ODA', 'MNC investment', 'NGOs like BRAC', 'Gates Foundation in health'],
               ['states provide education, infrastructure, regulation', 'developmental states (South Korea, China)', 'non-state actors depend on state frameworks'],
               'Non-state actors are increasingly significant, but states remain central in setting conditions for development.')],
    extended=[('Evaluate the role of one MNC or NGO in the development of a country you have studied.', 'E.g. Shell in Nigeria, Unilever in India, M-Pesa in Kenya, BRAC in Bangladesh; analyse benefits, costs and accountability; reach a judgement.', 8, 'long')],
))

